import{_ as t}from"./chunks/files.B17OUyrr.js";import{_ as i,c as e,o as r,a2 as o}from"./chunks/framework.CIiVzG-O.js";const _=JSON.parse('{"title":"qDiff のご紹介","description":"Mac で qDiff を使ってファイル・フォルダ・プロジェクトを比較する方法を、手短にご紹介します。","frontmatter":{"title":"qDiff のご紹介","description":"Mac で qDiff を使ってファイル・フォルダ・プロジェクトを比較する方法を、手短にご紹介します。"},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1794296122000}'),l={name:"ja/guide/introduction.md"};function s(n,a,d,f,c,h){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="qdiff-のご紹介" tabindex="-1">qDiff のご紹介 <a class="header-anchor" href="#qdiff-のご紹介" aria-label="Permalink to &quot;qDiff のご紹介&quot;">​</a></h1><p>qDiff が答える問いはひとつだけです。<strong>どこが変わったのか？</strong> 2 つのバージョンを 並べると、違っている部分がすべて色で示されるので、目で 1 行ずつ照らし合わせる 必要はもうありません。</p><img src="'+t+'" alt="2 つのファイルを並べて比較した画面" class="guide-shot"><h2 id="よく使われる-3-つの場面" tabindex="-1">よく使われる 3 つの場面 <a class="header-anchor" href="#よく使われる-3-つの場面" aria-label="Permalink to &quot;よく使われる 3 つの場面&quot;">​</a></h2><ul><li><strong>2 つのファイル</strong> —— 下書きと改訂版、設定の変更前後、同じツールから書き出した 2 つのデータ。行の中で変わった語がハイライトされます。</li><li><strong>2 つのフォルダ</strong> —— 作業用フォルダとそのバックアップ。新規・変更・削除された ファイルがすぐ見つかり、両側を再び同期できます。</li><li><strong>プロジェクトフォルダ</strong> —— 編集したものがすべて 1 つの一覧に集まります。 それぞれの変更を読んで、ウィンドウを切り替えずにコミットできます。</li></ul><p>画像、圧縮アーカイブ、プレーンテキストではないファイルも扱えます。 <a href="./more.html">その他の比較方法</a>もご覧ください。</p><h2 id="_3-ステップで始める" tabindex="-1">3 ステップで始める <a class="header-anchor" href="#_3-ステップで始める" aria-label="Permalink to &quot;3 ステップで始める&quot;">​</a></h2><ol><li>qDiff を開き、2 つのファイルまたはフォルダをウィンドウにドラッグします。 <strong>ファイル</strong>メニューから選ぶこともできます。</li><li>色の付いた行を見てください。横にある小さなマップをクリックするか、 前へ／次へボタンで、すべての変更を順にたどれます。</li><li>直したい箇所を編集・コピー・同期します。他の人にも見せたい場合は、 比較結果を画像として保存してください。</li></ol><div class="tip custom-block"><p class="custom-block-title">設定は不要です</p><p>最初の比較の前に、アカウントを作ったり何かを設定したりする必要はありません。 すべてオフラインで動作します。</p></div><h2 id="無料、そしてプライベート" tabindex="-1">無料、そしてプライベート <a class="header-anchor" href="#無料、そしてプライベート" aria-label="Permalink to &quot;無料、そしてプライベート&quot;">​</a></h2><p>すべての比較を無料でご利用いただけます。無料版ではタブバーに小さなマークが 表示されるだけです。一度きりの購入で、このマークは消えます。qDiff は選んだ ファイルを読み取るだけで、どこにも送信しません。詳しくは <a href="./../privacy/">プライバシーポリシー</a>をご覧ください。</p><h2 id="お困りですか" tabindex="-1">お困りですか？ <a class="header-anchor" href="#お困りですか" aria-label="Permalink to &quot;お困りですか？&quot;">​</a></h2><p>よくあるご質問は<a href="./faq.html">FAQ</a>にまとめています。それでも解決しない場合は、 <a href="./../guide/support.html">お問い合わせ</a>からご連絡ください。サポートいたします。</p>',13)])])}const m=i(l,[["render",s]]);export{_ as __pageData,m as default};
